import test from 'node:test';
import assert from 'node:assert/strict';
import { legalizePlanGraph, footprintEnvelope, type FootprintEnvelope } from '../eda/blocks/legalize.js';
import { planGraph } from '../src/blocks/graph.js';
import { contentHash } from '../src/blocks/library.js';
import type { PlanGraph, PlacedPart } from '../src/blocks/graph.js';
import type { BlockDef, BlockPart, BoardPlan, Pose } from '../src/blocks/contract.js';
const box = (w: number, h: number): FootprintEnvelope => ({ minX: -w / 2, maxX: w / 2, minY: -h / 2, maxY: h / 2, layers: ['top'] });
// SYNTHETIC fixtures exercise geometric failure modes, without supplier/hardware claims.
function part(ref: string, at: Pose): BlockPart { return { ref, at, mpn: 'SYNTHETIC', lcsc: 'SYNTHETIC', catalogReceipt: `sha256:${'a'.repeat(64)}`, datasheet: { url: 'https://example.invalid/synthetic', pages: '1' }, pinout: 'verified', pins: ref.startsWith('C') || ref.startsWith('R') ? { A: { pad: '1', role: 'passive' }, B: { pad: '2', role: 'passive' } } : { V: { pad: '1', role: 'power-in' } } }; }
function block(id = 'test', parts = [part('U1', { x: 0, y: 0 }), part('C1', { x: 0, y: 0 })]): BlockDef { return { schema: 'moki.block/1', id, version: 1, contentHash: 'a'.repeat(64), title: 'Synthetic placement', summary: 'No native verification', class: 'synthetic', status: 'unreviewed', provenance: { author: 'agent', reviews: [] }, parts, nets: [], ports: [], params: [], power: { sources: [], sinks: [] }, constraints: [] }; }
const plan = (blocks: BlockDef[]): BoardPlan => ({ schema: 'moki.plan/1', title: 'SYNTHETIC', layers: 2, board: { widthMm: 40, heightMm: 40 }, blocks: blocks.map(b => ({ inst: b.id, block: b.id, version: 1, params: {}, at: { x: 0, y: 0 } })), links: [] });
const envelopeMap = (graph: PlanGraph, b: FootprintEnvelope = box(1, .5)) => new Map(graph.parts.map(p => [p.part, p.localRef.startsWith('U') ? box(2, 2) : b]));
function worldBox(p: PlacedPart, b: FootprintEnvelope) {
  const a = (p.at.rotation ?? 0) * Math.PI / 180;
  const pts = [b.minX, b.maxX].flatMap(x => [b.minY, b.maxY].map(y => ({ x: p.at.x + x * Math.cos(a) - y * Math.sin(a), y: p.at.y + x * Math.sin(a) + y * Math.cos(a) })));
  return { minX: Math.min(...pts.map(p => p.x)), maxX: Math.max(...pts.map(p => p.x)), minY: Math.min(...pts.map(p => p.y)), maxY: Math.max(...pts.map(p => p.y)) };
}
function separation(a: FootprintEnvelope, b: FootprintEnvelope) { return Math.max(b.minX - a.maxX, a.minX - b.maxX, b.minY - a.maxY, a.minY - b.maxY); }
function assertLegal(result: PlanGraph, env: Map<BlockPart, FootprintEnvelope>) {
  for (let i = 0; i < result.parts.length; i++) for (let j = i + 1; j < result.parts.length; j++) assert.ok(separation(worldBox(result.parts[i]!, env.get(result.parts[i]!.part)!), worldBox(result.parts[j]!, env.get(result.parts[j]!.part)!)) >= .15 - 1e-7, `Envelope collision ${result.parts[i]!.ref}/${result.parts[j]!.ref}`);
  for (const p of result.parts) for (const c of p.block.constraints) if (c.kind === 'decoupling' && c.caps.includes(p.localRef)) {
    const ic = result.parts.find(q => q.inst === p.inst && q.localRef === c.ic)!;
    assert.ok(Math.hypot(p.at.x - ic.at.x, p.at.y - ic.at.y) <= c.maxDistanceMm + 1e-8, `Actual origin distance ${p.inst}.${p.localRef}`);
  }
}

test('passive legalization is deterministic, preserves fixed anchors/object identities and never mutates author data', () => {
  const b = block(); b.constraints.push({ kind: 'decoupling', ic: 'U1', powerPin: 'V', groundPin: 'G', caps: ['C1'], minUf: .1, maxDistanceMm: 2, citation: b.parts[0]!.datasheet });
  const p = plan([b]), graph = planGraph(p, [b]), envelopes = envelopeMap(graph), before = JSON.stringify({ p, graph });
  const one = legalizePlanGraph(p, graph, new Map(), { envelopes }), two = legalizePlanGraph(p, graph, new Map(), { envelopes });
  assert.deepEqual(one, two); assert.equal(one.changes.length, 1); assert.deepEqual(one.graph.parts[0]!.at, graph.parts[0]!.at);
  assert.ok(one.graph.parts.every((placed, i) => placed.part === graph.parts[i]!.part && placed.block === graph.parts[i]!.block));
  assert.equal(JSON.stringify({ p, graph }), before); assertLegal(one.graph, envelopes);
  assert.deepEqual(legalizePlanGraph(p, one.graph, new Map(), { envelopes }).changes, []);
});

test('all secondary ICs are placed before bypass, and distance uses their actual final world origin', () => {
  const b = block('led', [part('D1', { x: 0, y: 0 }), part('U1', { x: 0, y: 0 }), part('C1', { x: 0, y: 0 })]);
  b.constraints.push({ kind: 'decoupling', ic: 'U1', powerPin: 'V', groundPin: 'G', caps: ['C1'], minUf: .1, maxDistanceMm: 2, citation: b.parts[0]!.datasheet });
  const p = plan([b]), graph = planGraph(p, [b]), envelopes = envelopeMap(graph); envelopes.set(graph.parts[0]!.part, box(5, 5));
  const result = legalizePlanGraph(p, graph, new Map(), { envelopes }); assertLegal(result.graph, envelopes);
  const ic = result.graph.parts[1]!, cap = result.graph.parts[2]!;
  assert.ok(Math.hypot(ic.at.x, ic.at.y) > 3); assert.ok(Math.hypot(cap.at.x - ic.at.x, cap.at.y - ic.at.y) <= 2);
  assert.ok(Math.hypot(cap.at.x, cap.at.y) > 2); assert.equal(ic.at.rotation, 0);
});

test('secondary connector orientation is preserved even when its designator begins with C', () => {
  const connector = part('CN1', { x: 0, y: 0 });
  const b = block('connector', [part('U1', { x: 0, y: 0 }), connector]), p = plan([b]), graph = planGraph(p, [b]);
  const envelopes = envelopeMap(graph, box(4, 1));
  const result = legalizePlanGraph(p, graph, new Map(), { envelopes });
  assertLegal(result.graph, envelopes); assert.equal(result.graph.parts[1]!.at.rotation, 0);
});

test('transformed keepouts exclude only named parts in their own block', () => {
  const a = block('a', [part('U1', { x: 0, y: 0 })]), b = block('b', [part('U1', { x: 0, y: 0 })]);
  a.constraints.push({ kind: 'keepout', x: 4, y: 0, width: 2, height: 2, layers: ['top'], excludeParts: ['U1'], purpose: 'Rotated aperture', citation: a.parts[0]!.datasheet });
  const p = plan([a, b]); p.blocks[0]!.at = { x: 0, y: 0, rotation: 90 }; p.blocks[1]!.at = { x: 0, y: 4 };
  const graph = planGraph(p, [a, b]); assert.throws(() => legalizePlanGraph(p, graph, new Map(), { envelopes: new Map(graph.parts.map(q => [q.part, box(1, 1)])) }), /fixed anchor b.U1: keepout/);
  const only = block('only', [part('U1', { x: 0, y: 0 }), part('C1', { x: 4, y: 0 })]);
  only.constraints = [{ kind: 'keepout', x: 4, y: 0, width: 2, height: 2, layers: ['all'], excludeParts: ['C1'], purpose: 'Explicit local exception', citation: only.parts[0]!.datasheet }];
  const q = plan([only]), g = planGraph(q, [only]); assert.deepEqual(legalizePlanGraph(q, g, new Map(), { envelopes: envelopeMap(g) }).changes, []);
});

test('explicit rounded board bounds and impossible fixed-anchor packing fail without moving anchors', () => {
  const b = block('corner', [part('U1', { x: 4.5, y: 4.5 })]), p = plan([b]); p.board = { widthMm: 10, heightMm: 10, cornerRadiusMm: 2 };
  const graph = planGraph(p, [b]); assert.throws(() => legalizePlanGraph(p, graph, new Map(), { envelopes: new Map([[graph.parts[0]!.part, box(.2, .2)]]) }), /fixed anchor.*board bounds/);
  const full = block(), q = plan([full]); q.board = { widthMm: 10, heightMm: 10 };
  const g = planGraph(q, [full]), env = envelopeMap(g); env.set(g.parts[0]!.part, box(9.6, 9.6));
  assert.throws(() => legalizePlanGraph(q, g, new Map(), { envelopes: env }), /within 12 mm.*fixed anchors/);
  assert.deepEqual(g.parts[0]!.at, { x: 0, y: 0, rotation: 0 });
});

test('strict decoupling rejects physically impossible courtyard-to-origin bound instead of relaxing it', () => {
  const b = block(); b.constraints.push({ kind: 'decoupling', ic: 'U1', powerPin: 'V', groundPin: 'G', caps: ['C1'], minUf: 10, maxDistanceMm: 3, citation: b.parts[0]!.datasheet });
  const p = plan([b]), g = planGraph(p, [b]), env = new Map([[g.parts[0]!.part, box(4.1, 4.1)], [g.parts[1]!.part, box(3.91, 1.85)]]);
  assert.throws(() => legalizePlanGraph(p, g, new Map(), { envelopes: env }), /requires at least 3.125 mm.*declared 3 mm/);
});

test('converted footprint data formats preserve off-center courtyard/pad bounds and units', () => {
  const p = part('U1', { x: 0, y: 0 });
  const imported = { component: () => ({ props: { footprint: { type: 'footprint', props: { children: [
    { type: 'courtyardoutline', props: { outline: [{ x: -2, y: -1 }, { x: 3, y: -1 }, { x: 3, y: 2 }, { x: -2, y: 2 }] } },
    { type: 'smtpad', props: { pcbX: '3mm', pcbY: '0mm', width: '40mil', height: '1mm', portHints: ['pin1'], shape: 'rect' } },
  ] } } } }) };
  const b = footprintEnvelope(p, imported); assert.equal(b.minX, -2); assert.ok(Math.abs(b.maxX - 3.508) < 1e-9); assert.equal(b.minY, -1); assert.equal(b.maxY, 2);
  const fallback = footprintEnvelope(p, { component: () => ({ props: { footprint: [{ type: 'pcb_courtyard_rect', center: { x: 1, y: 2 }, width: 4, height: 2, layer: 'top' }, { type: 'pcb_smtpad', x: 0, y: 0, width: 1, height: 1, layer: 'top', shape: 'rect', port_hints: ['pin1'] }] } }) });
  assert.equal(fallback.minX, -1); assert.equal(fallback.maxX, 3); assert.equal(fallback.minY, -.5); assert.equal(fallback.maxY, 3);
  assert.throws(() => footprintEnvelope(p, { component: () => ({ props: { footprint: [] } }) }), /missing|degenerate/);
});

function capturedFixture(distance: number) {
  const captured = structuredClone(CAPTURED_LAYOUT), blocks = captured.blocks;
  for (const b of blocks) if (['i2s-amp-max98357a', 'ws2812b-v5-levelshift'].includes(b.id)) {
    // Explicit test-only reproduction of root's separately authored/reviewed v2 policy.
    for (const c of b.constraints) if (c.kind === 'decoupling') c.maxDistanceMm = distance;
    const { contentHash: _hash, status: _status, provenance, ...fields } = b;
    b.contentHash = contentHash({ ...fields, provenance: { author: provenance.author, authorId: provenance.authorId } });
  }
  const graph = planGraph(captured.plan, blocks);
  const envelopes = new Map(graph.parts.map(p => [p.part, captured.envelopes[p.ref]!]));
  assert.equal(graph.parts.length, 52); assert.ok([...envelopes.values()].every(Boolean));
  return { plan: captured.plan, graph, envelopes };
}

test('captured failed 52-part native geometry exposes v1 impossible3mm policy and legalizes explicit4mm revision', () => {
  const invalid = capturedFixture(3); assert.throws(() => legalizePlanGraph(invalid.plan, invalid.graph, new Map(), { envelopes: invalid.envelopes }), /requires at least 3.125 mm/);
  const valid = capturedFixture(4), before = JSON.stringify(valid.graph);
  const result = legalizePlanGraph(valid.plan, valid.graph, new Map(), { envelopes: valid.envelopes });
  assert.ok(result.changes.length >= 10); assertLegal(result.graph, valid.envelopes);
  for (const p of result.graph.parts) if (p.localRef === p.block.parts[0]!.ref) assert.deepEqual(p.at, valid.graph.parts.find(q => q.ref === p.ref)!.at);
  assert.equal(JSON.stringify(valid.graph), before); assert.deepEqual(legalizePlanGraph(valid.plan, valid.graph, new Map(), { envelopes: valid.envelopes }), result);
  assert.deepEqual(legalizePlanGraph(valid.plan, result.graph, new Map(), { envelopes: valid.envelopes }).changes, []);
});

